//! Decimal `AVG` and division rounding against Spark 4.2: each case of
//! `tests/fixtures/spark-4.2.0/decimal-rounding-goldens.json` (generated by
//! `tests/scripts/gen_decimal_rounding_goldens.py` from a real Spark run)
//! runs through a session over the fixture's tables and must give Spark's
//! types and rows exactly. Results that need rounding `HALF_UP` at the result
//! scale (negatives round away from zero) catch an engine that truncates.
#![cfg(test)]

use std::fmt::Write as _;
use std::path::Path;
use std::sync::Arc;

use arrow_array::cast::AsArray;
use arrow_array::types::{Decimal64Type, Decimal128Type, Int32Type, Int64Type};
use arrow_array::{Array, ArrayRef, Decimal128Array, Int32Array, RecordBatch, StringArray};
use arrow_schema::{DataType, Field, Schema};
use futures::executor::block_on;
use krishiv_session::Session;
use serde_json::Value;

/// Known gaps: case id and what the engine does until fixed (each is a queue item).
const GAPS: [(&str, &str); 0] = [];

fn fixture() -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/decimal-rounding-goldens.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// `decimal(p,s)` as `(p, s)`.
fn decimal(t: &str) -> Option<(u8, i8)> {
    let inner = t.strip_prefix("decimal(")?.strip_suffix(')')?;
    let (p, s) = inner.split_once(',')?;
    Some((p.trim().parse().ok()?, s.trim().parse().ok()?))
}

/// The unscaled value of decimal text with `scale` digits after the point.
fn unscaled(text: &str, scale: i8) -> i128 {
    let negative = text.starts_with('-');
    let digits = text.trim_start_matches('-');
    let (int, frac) = digits.split_once('.').unwrap_or((digits, ""));
    let mut frac = frac.to_owned();
    frac.extend(std::iter::repeat_n(
        '0',
        usize::try_from(scale).unwrap() - frac.len(),
    ));
    let v: i128 = format!("{int}{frac}").parse().unwrap();
    if negative { -v } else { v }
}

/// A column of Spark type `t` from the fixture's text values.
fn column(t: &str, values: &[Option<&str>]) -> (DataType, ArrayRef) {
    match t {
        "int" => (
            DataType::Int32,
            Arc::new(Int32Array::from_iter(
                values.iter().map(|v| v.map(|v| v.parse::<i32>().unwrap())),
            )),
        ),
        "string" => (
            DataType::Utf8,
            Arc::new(StringArray::from_iter(values.iter().copied())),
        ),
        t => {
            // Decimals on the canonical carrier, as tables hold them.
            let (p, s) = decimal(t).unwrap_or_else(|| panic!("fixture type {t}"));
            let a = Decimal128Array::from_iter(values.iter().map(|v| v.map(|v| unscaled(v, s))))
                .with_precision_and_scale(p, s)
                .unwrap();
            (DataType::Decimal128(p, s), Arc::new(a))
        }
    }
}

fn session(g: &Value) -> Session {
    let s = Session::new().unwrap();
    for (name, table) in g["tables"].as_object().unwrap() {
        let rows = table["rows"].as_array().unwrap();
        let mut fields = Vec::new();
        let mut columns = Vec::new();
        for (i, c) in table["columns"].as_array().unwrap().iter().enumerate() {
            let values: Vec<Option<&str>> = rows.iter().map(|r| r[i].as_str()).collect();
            let (t, a) = column(c["type"].as_str().unwrap(), &values);
            fields.push(Field::new(
                c["name"].as_str().unwrap(),
                t,
                c["nullable"].as_bool().unwrap(),
            ));
            columns.push(a);
        }
        let schema = Arc::new(Schema::new(fields));
        let batch = RecordBatch::try_new(Arc::clone(&schema), columns).unwrap();
        s.register_batches(name, schema, vec![batch]).unwrap();
    }
    s
}

/// A result value as the fixture writes it, by Spark type `t`.
fn text(a: &ArrayRef, i: usize) -> Value {
    // A `VOID` column is all NULL (its nulls are logical, not in a bitmap).
    if a.is_null(i) || a.data_type() == &DataType::Null {
        return Value::Null;
    }
    let s = match a.data_type() {
        DataType::Int32 => a.as_primitive::<Int32Type>().value(i).to_string(),
        DataType::Int64 => a.as_primitive::<Int64Type>().value(i).to_string(),
        DataType::Decimal64(_, s) => {
            plain(i128::from(a.as_primitive::<Decimal64Type>().value(i)), *s)
        }
        DataType::Decimal128(_, s) => plain(a.as_primitive::<Decimal128Type>().value(i), *s),
        DataType::Utf8 | DataType::Utf8View | DataType::LargeUtf8 => arrow_cast_string(a, i),
        t => panic!("result type {t}"),
    };
    Value::String(s)
}

fn arrow_cast_string(a: &ArrayRef, i: usize) -> String {
    match a.data_type() {
        DataType::Utf8View => a.as_string_view().value(i).to_owned(),
        DataType::LargeUtf8 => a.as_string::<i64>().value(i).to_owned(),
        _ => a.as_string::<i32>().value(i).to_owned(),
    }
}

fn plain(v: i128, scale: i8) -> String {
    let digits = v.unsigned_abs().to_string();
    let scale = usize::try_from(scale).unwrap();
    let sign = if v < 0 { "-" } else { "" };
    if scale == 0 {
        return format!("{sign}{digits}");
    }
    let padded = format!("{digits:0>width$}", width = scale + 1);
    let (int, frac) = padded.split_at(padded.len() - scale);
    format!("{sign}{int}.{frac}")
}

/// The mismatches of one case, as text (empty when it matches).
fn check(s: &Session, tables: &[&str], case: &Value) -> String {
    let mut out = String::new();
    let conf = s.conf();
    let settings = case["conf"].as_object().unwrap();
    for (k, v) in settings {
        conf.set(k, v.as_str().unwrap()).unwrap();
    }
    let sql = case["sql"].as_str().unwrap();
    let result = block_on(async {
        let df = s.sql(sql).await?;
        let schema = df.schema().await?;
        let batches = df.collect().await?;
        Ok::<_, krishiv_common::error::KrishivError>((schema, batches))
    });
    for k in settings.keys() {
        conf.unset(k).unwrap();
    }
    let id = case["id"].as_str().unwrap();
    if let Some((_, class)) = GAPS.iter().find(|(g, _)| *g == id) {
        match result {
            Err(e) if e.error_class().name() == *class => {}
            other => {
                let _ = writeln!(out, "{id}: known gap changed (update GAPS): {other:?}");
            }
        }
        return out;
    }
    match (case["ok"].as_bool().unwrap(), result) {
        (true, Ok((schema, batches))) => {
            let want = case["output"].as_array().unwrap();
            if schema.fields().len() != want.len() {
                let _ = writeln!(
                    out,
                    "{id}: {} columns, Spark {}",
                    schema.fields().len(),
                    want.len()
                );
                return out;
            }
            for (f, w) in schema.fields().iter().zip(want) {
                let ty = krishiv_types::DataType::from_arrow(f.data_type())
                    .map(|t| t.simple_string())
                    .unwrap_or_default();
                if f.name() != w["name"].as_str().unwrap()
                    || ty != w["type"].as_str().unwrap()
                    || f.is_nullable() != w["nullable"].as_bool().unwrap()
                {
                    let _ = writeln!(
                        out,
                        "{id}: column {}:{ty}:{} vs Spark {}",
                        f.name(),
                        f.is_nullable(),
                        w
                    );
                }
            }
            let mut got: Vec<Vec<Value>> = Vec::new();
            for b in &batches {
                for i in 0..b.num_rows() {
                    got.push(b.columns().iter().map(|c| text(c, i)).collect());
                }
            }
            let mut want_rows: Vec<Vec<Value>> = case["rows"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| r.as_array().unwrap().clone())
                .collect();
            let key = |r: &Vec<Value>| serde_json::to_string(r).unwrap();
            got.sort_by_key(key);
            want_rows.sort_by_key(key);
            if got != want_rows {
                let _ = writeln!(out, "{id}: rows\n  got  {got:?}\n  want {want_rows:?}");
            }
        }
        (false, Err(e)) => {
            let class = e.error_class().name();
            let want = case["error_class"].as_str().unwrap();
            let params: serde_json::Map<String, Value> = e
                .message_parameters()
                .iter()
                .map(|(k, v)| ((*k).to_owned(), Value::String(v.clone())))
                .collect();
            // The fixture's tables are temporary views in Spark, whose
            // suggestions qualify columns by the view's name; here they are
            // catalog tables, which Spark's suggestions do not qualify.
            let mut want_params = case["message_parameters"].as_object().unwrap().clone();
            if let Some(Value::String(p)) = want_params.get_mut("proposal") {
                for name in tables {
                    *p = p.replace(&format!("`{name}`."), "");
                }
            }
            if class != want || params != want_params {
                let _ = writeln!(
                    out,
                    "{id}: error {class} {params:?}\n  Spark {want} {want_params:?}"
                );
            }
        }
        (true, Err(e)) => {
            let _ = writeln!(out, "{id}: failed: {e}");
        }
        (false, Ok(_)) => {
            let _ = writeln!(out, "{id}: ran; Spark raised {}", case["error_class"]);
        }
    }
    out
}

#[test]
fn decimal_rounding_matches_spark() {
    let g = fixture();
    let s = session(&g);
    let cases = g["cases"].as_array().unwrap();
    let tables: Vec<&str> = g["tables"]
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect();
    let mut report = String::new();
    for case in cases {
        report.push_str(&check(&s, &tables, case));
    }
    assert!(cases.len() >= 39, "the fixture lost cases");
    assert!(report.is_empty(), "mismatches against Spark:\n{report}");
}
